@startuml

class House {
  + Address : string
  + BuildingMaterial : string
}

class Basement {
  + Name : string
  + Size : float
}

class EarthBasement extends Basement {
  + HumidityLevel : float
}

class ConcreteBasement extends Basement {
}

class SemiDetachedHouse extends House {
  + HasOwnGarden : boolean
  + WindowCount : int
}

class Carport {
  + IsDoubleCarport : boolean
  + HasFlatRoof : boolean
}

class Garage {
  + HasAutomaticGarageDoor : boolean
}

class Company {
  + Name : string
  + Address : string
}

class JobLog {
  + Hours : float
  + AgreedPrice : float
}

House "0..1" *-- "0..1" Basement
House "1" -- "0..*" Company : serviced by
Company "1" -- "0..*" JobLog : carries out
House "1" -- "0..*" JobLog : has
JobLog "0..*" -- "1" House
JobLog "0..*" -- "1" Company

SemiDetachedHouse "1" -- "2" Carport
SemiDetachedHouse "1" -- "0..1" Garage

@enduml

